# Independent algebraic equilibrium/invariant checks.
a,b=s.symbols('a b',positive=True)
for label,fx,fy,points in [('3',a*(R(1,2)-a/250-b/1000),b*(R(2,5)-b/1000-a/500),[(0,0),(125,0),(0,400),(50,300)]),('10',a*(2-b/100),b*(-R(1,2)+a/10000),[(0,0),(5000,200)]),('11',a*(R(2,25)*(1-a/5000)-b/1000),b*(-R(1,50)+a/50000),[(0,0),(5000,0),(1000,64)]),('12',a*(2-a/5000-b/100),b*(-R(1,2)+a/10000),[(0,0),(10000,0),(5000,100)])]:
 for aa,bb in points:check(label+' equilibrium '+str((aa,bb)),fx.subs({a:aa,b:bb})**2+fy.subs({a:aa,b:bb})**2)
H=s.log(a)/50+R(2,25)*s.log(b)-a/50000-b/1000
check('9 conserved along trajectory',s.diff(H,a)*a*(R(2,25)-b/1000)+s.diff(H,b)*b*(-R(1,50)+a/50000))
